import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        // Grant TIMELOCK_ADMIN_ROLE to admin account (address(this) by default setup, but we need to ensure it has the admin role to grant roles)
        // In the constructor, _setupRole is called for TIMELOCK_ADMIN_ROLE to _msgSender() and address(this).
        // _msgSender() in this context is the setUp() caller, which is the test contract itself (address(this)).
        // So address(this) has TIMELOCK_ADMIN_ROLE and is admin for all roles.
        // We'll use this account to grant roles.
    }

    function testFuzz_property(bytes32 role, address account) public {
        // The reference C's hasRole returns the actual membership boolean.
        // The mutant returns the negation, returning true when not a member and false when a member.
        // To observe the difference, we need an account that is a member of the role.
        // We'll grant the role to the account and then check hasRole.
        // This requires that the caller (address(this)) has the admin role for 'role'.
        // Since TIMELOCK_ADMIN_ROLE is the admin for all roles and address(this) has it,
        // we can grant any role to any account.
        vm.assume(account != address(0));
        vm.assume(role != bytes32(0));
        // Grant the role to account
        vm.prank(address(this));
        c.grantRole(role, account);
        // Now, in the reference, hasRole(role, account) should be true.
        // In the mutant, it will be false (negation of true).
        bool hasRoleResult = c.hasRole(role, account);
        assertTrue(hasRoleResult, "hasRole must return true for a granted role");
    }
}

