pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(address user, bytes32 role) public {
        // The reference grants a role to user via internal _grantRole which sets membership to true.
        // We must trigger a path that grants the role internally without reverting.
        // _setupRole is internal and not directly callable, but it is invoked in the constructor
        // for PROPOSER_ROLE, EXECUTOR_ROLE, TIMELOCK_ADMIN_ROLE for msg.sender and address(this).
        // However, we need a way to grant an arbitrary role to user through the public interface.
        // grantRole requires the caller to have admin role, which is not given for arbitrary roles.
        // But we can use the fact that the constructor sets up roles for proposers/executors passed in.
        // Since we didn't pass any in setUp, only msg.sender (this test contract) and address(this) got roles.
        // To test a general property, we need to set up a role grant to user. We will use the DEFAULT_ADMIN_ROLE
        // which by default has itself as admin (adminRole = bytes32(0) maps to adminRole 0x00).
        // Actually, getRoleAdmin(DEFAULT_ADMIN_ROLE) returns adminRole which is uninitialized (0), so it's 0.
        // grantRole(DEFAULT_ADMIN_ROLE, user) requires admin role check: getRoleAdmin(DEFAULT_ADMIN_ROLE) = 0,
        // so it checks hasRole(0, caller). Since no one has been granted role 0, it will revert.
        // We can call _setupRole internally? No, it's internal.
        // But we can call grantRole for TIMELOCK_ADMIN_ROLE if we are an admin of that role.
        // TIMELOCK_ADMIN_ROLE's admin is itself (set in constructor). The constructor gave TIMELOCK_ADMIN_ROLE
        // to msg.sender (this test contract) and address(c). So this test contract has TIMELOCK_ADMIN_ROLE.
        // Thus we can call c.grantRole(TIMELOCK_ADMIN_ROLE, user) because we have that role.
        // But the property should be general for any role? We can test for TIMELOCK_ADMIN_ROLE and random roles.
        // However, the bug is in hasRole which is public view, so we can directly test its return value after granting.
        // Granting TIMELOCK_ADMIN_ROLE to user via grantRole, then checking hasRole.
        vm.assume(user != address(0) && user != address(this) && user != address(c));
        vm.assume(role != bytes32(0) && role != c.TIMELOCK_ADMIN_ROLE() && role != c.PROPOSER_ROLE() && role != c.EXECUTOR_ROLE());
        // Grant the fuzzed role to user: we need to be an admin of that role. Since we are not, we must
        // first set ourselves as admin of that role. _setRoleAdmin is internal, but setRoleAdmin is not exposed.
        // This is a problem. We need a way to grant any arbitrary role to user without having admin rights.
        // But the contract's public interface only allows grantRole if we have admin role.
        // However, we can use the TIMELOCK_ADMIN_ROLE admin to change admin of other roles? No.
        // Actually, the only way to grant an arbitrary role is to be the admin of that role.
        // The constructor set TIMELOCK_ADMIN_ROLE as admin of PROPOSER_ROLE and EXECUTOR_ROLE.
        // So as holder of TIMELOCK_ADMIN_ROLE, we can grant PROPOSER_ROLE and EXECUTOR_ROLE, and also
        // TIMELOCK_ADMIN_ROLE itself. But not arbitrary role.
